 1	const PUNYCODE_PREFIX: &str = "xn--";
 2	
 3	pub fn to_ascii(input: &str) -> String {
 4	    let mut output = String::with_capacity(PUNYCODE_PREFIX.len() + input.len());
 5	    output.push_str(PUNYCODE_PREFIX);
 6	    output.push_str(&to_lower(input));
 7	    output
 8	}
 9	
10	pub fn to_unicode(input: &str) -> String {
11	    input
12	        .strip_prefix(PUNYCODE_PREFIX)
13	        .unwrap_or(input)
14	        .to_string()
15	}
16	
17	pub fn punycode_encode(input: &str) -> String {
18	    let mut output = String::with_capacity(PUNYCODE_PREFIX.len() + input.len());
19	    output.push_str(PUNYCODE_PREFIX);
20	    output.push_str(input);
21	    output
22	}
23	
24	pub fn punycode_decode(input: &str) -> String {
25	    to_unicode(input)
26	}
27	
28	pub fn to_lower(input: &str) -> String {
29	    input.to_ascii_lowercase()
30	}
31	
32	pub fn normalize(input: &str) -> String {
33	    to_lower(input)
34	}

